begin;
create extension if not exists pgtap with schema extensions;
select plan(26);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_user_meta_data,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99700000-0000-4000-8000-000000000001','authenticated','authenticated','loyalty-owner@example.test','',now(),'{}',now(),now());
set local role authenticated;select set_config('request.jwt.claim.sub','99700000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.create_business('loyalty-test','Loyalty Test','Loyalty Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.loyalty_org',(select id::text from public.organizations where slug='loyalty-test'),true);select set_config('test.loyalty_branch',(select id::text from public.branches where organization_id=current_setting('test.loyalty_org')::uuid and code='main'),true);
select is(public.can_business_permission(current_setting('test.loyalty_org')::uuid,'loyalty.manage'),true,'Owner receives loyalty management permission');
select throws_ok($$select public.save_loyalty_rule(current_setting('test.loyalty_org')::uuid,null,'Early','earn',100,1,null,100,null,true)$$,'42501','Permission denied.','Disabled loyalty module rejects rule changes');
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.loyalty_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99700000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'product_catalog',true,'{}');select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'inventory',true,'{"allow_negative_stock":false}');select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'sales',true,'{}');select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'pos',true,'{}');select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'crm',true,'{}');
select lives_ok($$select public.set_business_module_state(current_setting('test.loyalty_org')::uuid,'loyalty',true,'{"points_label":"Suki Points","automatic_sale_awards":true}')$$,'Loyalty activates with CRM and Sales dependencies');
select throws_ok($$select public.record_customer_loyalty(current_setting('test.loyalty_org')::uuid,gen_random_uuid(),'earn',10,'Bypass','manual',null)$$,'P0001','Use the Loyalty module for point changes.','Enabled Loyalty module prevents legacy CRM activity from drifting the balance');
select results_eq($$select name,rule_type,spend_amount,points_amount from public.loyalty_rules where organization_id=current_setting('test.loyalty_org')::uuid$$,$$select 'Standard earning'::text,'earn'::text,100::numeric,1$$,'Activation installs the PHP 100 to one point example rule');
select set_config('test.loyalty_customer',public.save_crm_customer(current_setting('test.loyalty_org')::uuid,null,current_setting('test.loyalty_branch')::uuid,'Maria Santos','09171234567','','{}',null,null,'retail','{}','')::text,true);select set_config('test.loyalty_product',public.save_catalog_product(current_setting('test.loyalty_org')::uuid,null,null,'product','Loyalty Item','',null,null,'piece',125,80,'exempt',0,'active',false,'[{"name":"Default","sku":"LOYALTY-001","barcode":"4800000000099","attributes":{},"status":"active"}]','[]')::text,true);select set_config('test.loyalty_variant',(select id::text from public.product_variants where product_id=current_setting('test.loyalty_product')::uuid),true);select set_config('test.loyalty_item',public.configure_inventory_item(current_setting('test.loyalty_org')::uuid,null,current_setting('test.loyalty_variant')::uuid,2,5,true)::text,true);select set_config('test.loyalty_location',(select id::text from public.inventory_locations where organization_id=current_setting('test.loyalty_org')::uuid),true);select public.record_stock_movement(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_item')::uuid,current_setting('test.loyalty_location')::uuid,'opening_balance',20,80,'Opening','loyalty-opening');
select lives_ok($$select public.save_pos_transaction(current_setting('test.loyalty_org')::uuid,null,current_setting('test.loyalty_branch')::uuid,current_setting('test.loyalty_location')::uuid,current_setting('test.loyalty_customer')::uuid,'completed','99700000-0000-4000-8000-000000000101',now(),('[{"productVariantId":"'||current_setting('test.loyalty_variant')||'","quantity":2,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":250,"reference":""}]')$$,'Completed customer sale atomically awards loyalty points');select set_config('test.loyalty_sale',(select id::text from public.sales_transactions where client_transaction_id='99700000-0000-4000-8000-000000000101'),true);
select results_eq($$select points_balance,lifetime_earned from public.customer_loyalty_balances where customer_id=current_setting('test.loyalty_customer')::uuid$$,$$select 2,2$$,'Balance materializes two points from PHP 250');
select results_eq($$select transaction_type,points_delta,balance_after from public.loyalty_transactions where sale_id=current_setting('test.loyalty_sale')::uuid$$,$$select 'earn'::text,2,2$$,'Award appends an immutable earning transaction');
select results_eq($$select points_awarded,count(*)over()from public.loyalty_award_receipts where sale_id=current_setting('test.loyalty_sale')::uuid$$,$$select 2,1::bigint$$,'Sale award receipt records idempotent processing');
select results_eq($$select activity_type,points_delta from public.customer_loyalty_activity where reference_id=(select id from public.loyalty_transactions where sale_id=current_setting('test.loyalty_sale')::uuid)$$,$$select 'earn'::text,2$$,'Loyalty award is visible in CRM activity');
select lives_ok($$select public.award_sale_loyalty(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_sale')::uuid,'sale:'||current_setting('test.loyalty_sale'))$$,'Sale award can be replayed safely');
select results_eq($$select count(*),max(points_balance)from public.loyalty_transactions join public.customer_loyalty_balances using(organization_id,customer_id)where sale_id=current_setting('test.loyalty_sale')::uuid$$,$$select 1::bigint,2$$,'Replay does not duplicate points');
select set_config('test.loyalty_redeem_rule',public.save_loyalty_rule(current_setting('test.loyalty_org')::uuid,null,'PHP 10 reward','redeem',null,2,10,100,null,true)::text,true);select results_eq($$select points_amount,redemption_value from public.loyalty_rules where id=current_setting('test.loyalty_redeem_rule')::uuid$$,$$select 2,10::numeric$$,'Business can configure a redemption rule');
select set_config('test.loyalty_redemption',public.redeem_loyalty_points(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_customer')::uuid,current_setting('test.loyalty_redeem_rule')::uuid,2,'redeem:test:001','Welcome reward')::text,true);
select results_eq($$select points_balance,lifetime_redeemed from public.customer_loyalty_balances where customer_id=current_setting('test.loyalty_customer')::uuid$$,$$select 0,2$$,'Redemption safely materializes the customer balance');
select results_eq($$select transaction_type,points_delta,monetary_value,balance_after from public.loyalty_transactions where id=current_setting('test.loyalty_redemption')::uuid$$,$$select 'redeem'::text,-2,10::numeric,0$$,'Redemption history records points and PHP value');
select results_eq($$select sum(points_allocated)from public.loyalty_redemption_allocations where redemption_transaction_id=current_setting('test.loyalty_redemption')::uuid$$,$$select 2::bigint$$,'Redemption allocates FIFO against earning lots');
select lives_ok($$select public.redeem_loyalty_points(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_customer')::uuid,current_setting('test.loyalty_redeem_rule')::uuid,2,'redeem:test:001','Welcome reward')$$,'Redemption can be replayed with the same key');
select results_eq($$select count(*),min(points_balance)from public.loyalty_transactions join public.customer_loyalty_balances using(organization_id,customer_id)where idempotency_key='redeem:test:001'$$,$$select 1::bigint,0$$,'Redemption idempotency prevents duplicate deductions');
select set_config('test.loyalty_earn_rule',(select id::text from public.loyalty_rules where organization_id=current_setting('test.loyalty_org')::uuid and rule_type='earn'),true);select lives_ok($$select public.save_loyalty_rule(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_earn_rule')::uuid,'Expiring earning','earn',100,1,null,10,1,true)$$,'Earning expiry is configurable per business');
select lives_ok($$select public.save_pos_transaction(current_setting('test.loyalty_org')::uuid,null,current_setting('test.loyalty_branch')::uuid,current_setting('test.loyalty_location')::uuid,current_setting('test.loyalty_customer')::uuid,'completed','99700000-0000-4000-8000-000000000102',now(),('[{"productVariantId":"'||current_setting('test.loyalty_variant')||'","quantity":1,"discountAmount":0}]')::jsonb,'[{"method":"cash","amount":125,"reference":""}]')$$,'A later sale creates an expiring earning lot');
select results_eq($$select points_balance from public.customer_loyalty_balances where customer_id=current_setting('test.loyalty_customer')::uuid$$,$$select 1$$,'Later sale awards one available point');
select is(public.process_loyalty_expiries(current_setting('test.loyalty_org')::uuid,now()+interval'2 days'),1,'Expiry processor reports the expired point');
select results_eq($$select points_balance,lifetime_expired from public.customer_loyalty_balances where customer_id=current_setting('test.loyalty_customer')::uuid$$,$$select 0,1$$,'Expiry safely updates balance totals');
select results_eq($$select transaction_type,points_delta,balance_after from public.loyalty_transactions where transaction_type='expire'and customer_id=current_setting('test.loyalty_customer')::uuid$$,$$select 'expire'::text,-1,0$$,'Expiry appends auditable transaction history');
reset role;select throws_ok($$update public.loyalty_transactions set points_delta=999 where id=current_setting('test.loyalty_redemption')::uuid$$,'P0001','Loyalty history is immutable.','Ledger rows cannot be rewritten even by direct SQL');set local role authenticated;select set_config('request.jwt.claim.sub','99700000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99700000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$insert into public.loyalty_transactions(organization_id,customer_id,transaction_type,points_delta,balance_after,idempotency_key,created_by)values(current_setting('test.loyalty_org')::uuid,current_setting('test.loyalty_customer')::uuid,'earn',500,500,'bypass',auth.uid())$$,'42501','permission denied for table loyalty_transactions','Clients cannot bypass loyalty RPC boundaries');
select * from finish();rollback;
